function photoClue(p){
 const context=p.clue||p.alt.replace(/\b(?:18|19|20)\d{2}\b/g,'[year hidden]');
 const whisper=difficulty===0?ERA_DECADE[Math.min(2020,Math.floor(p.year/10)*10)]:difficulty===1?ERA_GENERATION[Math.min(2000,Math.floor(p.year/25)*25)]:'';
 return context+(whisper?`<em class="era-whisper">${whisper}</em>`:'');
}
const ERA_DECADE={
 1850:'The world back then: sitters hold perfectly still for slow exposures, and steam trains are still a wonder.',
 1860:'The world back then: glass plates travel by cart, telegraph wires are crossing continents, and America is torn by civil war.',
 1870:'The world back then: the telephone is a brand-new invention, and the Raj is at its most formal.',
 1880:'The world back then: electric light is a marvel in a few rich cities, and the motor car has only just sputtered into life.',
 1890:'The world back then: bicycles are the craze, and the first moving pictures flicker in darkened halls.',
 1900:'The world back then: a new century, noisy rare motor cars, and the very first aeroplanes leaving the ground.',
 1910:'The world back then: a great war rages, a deadly flu follows it, and silent films pack the halls.',
 1920:'The world back then: jazz and silent cinema in the West, and a growing call for swaraj in India.',
 1930:'The world back then: a Great Depression, films that have just learned to talk, and Gandhi marching for salt.',
 1940:'The world back then: a second world war, and then the end of empires.',
 1950:'The world back then: a young republic builds dams and steel plants, while television reaches Western living rooms.',
 1960:'The world back then: the space race is on, colour film is spreading, and the Beatles are on the radio.',
 1970:'The world back then: flared trousers, pocket calculators, and colour photographs everywhere.',
 1980:'The world back then: Walkmans, the first personal computers, and colour TV arriving in Indian homes.',
 1990:'The world back then: the Cold War is over, India opens its economy, and the World Wide Web is born.',
 2000:'The world back then: mobile phones in every pocket, and digital cameras replacing film.',
 2010:'The world back then: smartphones and social media take over, and "selfie" becomes a word.',
 2020:'The world back then: a pandemic reshapes daily life, and video calls become normal.'
};
const ERA_GENERATION={
 1850:'Think of the first age of photography: long exposures, steam and the telegraph.',
 1875:'Think of late Victorian times: gaslight, horse-drawn streets and the first electric bulbs.',
 1900:'Think of the dawn of flight and motor cars, and a world at war.',
 1925:'Think of the years between the Depression and the end of empires.',
 1950:'Think of the post-war world: new nations, the space race, and black-and-white giving way to colour.',
 1975:'Think of colour film and the first home computers, up to the end of the Cold War.',
 2000:'Think of the digital age, with a camera in every pocket.'
};
function neighbourFace(shape,happy){return `<svg class="neighbourface" viewBox="0 0 64 64" aria-hidden="true">${shape===1?'<path class="facebody" d="M32 4 61 57H3Z"/>':'<rect class="facebody" x="7" y="7" width="50" height="50" rx="10"/>'}<circle cx="24" cy="33" r="2.8"/><circle cx="40" cy="33" r="2.8"/><path class="facemouth" d="${happy?'M23 41Q32 52 41 41':'M24 47Q32 39 40 47'}"/></svg>`}
/* Two optional discoveries; daily-five progress remains independent. */
const extraGames=[['Time Lens','Look closely. What year are you looking at?','Observation','Curious','3 photos','◉'],['Little Neighbours','Small moves. Surprisingly big changes.','Experiment','Play & learn','Puzzle + sandbox','▲ ■ ▲']];
function renderExtras(){if(!$('#extras'))return; $('#extras').innerHTML=extraGames.map((g,j)=>{let i=j+5;return `<button class="card ${state(i).done?'is-complete':''}" data-extra="${i}"><div class="cardtop"><span>${g[2]}</span><span class="level">NEW · ${levelName()}</span></div><div class="art" aria-hidden="true">${g[5]}</div><h3>${g[0]}</h3><p>${g[1]}</p><div class="cardbottom"><span class="${state(i).done?'completion-badge':''}">${state(i).done?'✓ Completed':g[4]}</span><span>↗</span></div></button>`}).join('');document.querySelectorAll('[data-extra]').forEach(b=>b.onclick=()=>openExtra(+b.dataset.extra))}
function openExtra(i){active=i;state(i).started=true;persist();let g=extraGames[i-5];$('#gtype').textContent='A little extra · '+g[2];$('#gtitle').textContent=g[0];$('#board').innerHTML='';$('#actions').innerHTML='';msg('');if(i===5)timeLens();else neighbours();let dlg=$('#game');if(dlg&&!dlg.open)dlg.showModal()}
const baseSetup=setup;setup=function(){baseSetup();renderExtras()};
// v4: every day pairs one history-shaping photograph, one Indian-context photograph and one more scene. Retired entries stay in PHOTO_BANK so saved rounds still resolve.
const ACTIVE_PHOTOS=PHOTO_BANK.filter(p=>!p.retired);
const ICONIC_PHOTO_CYCLE=shuffle(ACTIVE_PHOTOS.filter(p=>p.iconic),rng('iconic-photo-cycle-v4')).slice(0,61);
const INDIA_PHOTO_CYCLE=shuffle(ACTIVE_PHOTOS.filter(p=>p.india&&!p.iconic),rng('india-photo-cycle-v4')).slice(0,61);
const CYCLE_PHOTO_IDS=new Set([...ICONIC_PHOTO_CYCLE,...INDIA_PHOTO_CYCLE].map(p=>p.image));
const WORLD_PHOTO_CYCLE=shuffle(ACTIVE_PHOTOS.filter(p=>!CYCLE_PHOTO_IDS.has(p.image)),rng('world-photo-cycle-v4')).slice(0,61);
function photoSet(d){const i=mod(calendarIndex(d),61);return shuffle([ICONIC_PHOTO_CYCLE[i],INDIA_PHOTO_CYCLE[i],WORLD_PHOTO_CYCLE[i]],rng('photo-order-v4-'+i))}
// v3 schedule over the original 183 entries, kept only for Time Lens Duels saved before v4.
const LEGACY_PHOTO_BANK=PHOTO_BANK.slice(0,183);
const LEGACY_INDIA_CYCLE=shuffle(LEGACY_PHOTO_BANK.filter(p=>p.india),rng('india-photo-cycle-v3')).slice(0,61);
const LEGACY_INDIA_IDS=new Set(LEGACY_INDIA_CYCLE.map(p=>p.image));
const LEGACY_WORLD_CYCLE=shuffle(LEGACY_PHOTO_BANK.filter(p=>!LEGACY_INDIA_IDS.has(p.image)),rng('world-photo-cycle-v3')).slice(0,122);
function legacyPhotoSet(d){const i=mod(calendarIndex(d),61);return [LEGACY_INDIA_CYCLE[i],LEGACY_WORLD_CYCLE[i*2],LEGACY_WORLD_CYCLE[i*2+1]]}
function timeLens(){let s=state(5);if(!s.photoIds){s.photoIds=(s.answers?.length?shuffle(PHOTO_BANK.slice(0,6),rng(day+'photographs')).slice(0,3):photoSet(day)).map(p=>p.image)}let set=s.photoIds.map(id=>PHOTO_BANK.find(p=>p.image===id));persist();s.answers||=[];let index=Math.min(s.answers.length,2);$('#rules').textContent='Three real archive photographs. Slide or type your year, then discover the story. Up to 1,000 points each; every year away costs 20 points. Indian context meets scenes from around the world. Every day brings one photograph that shaped history, one from India and one more scene; 183 photographs cover a 61-day cycle without repeats in newly started rounds. Previously started rounds keep their original photographs. Gentle gives a date window, Medium gives a visual clue, Tricky gives just the photograph.';function draw(){ $('#actions').innerHTML='';if(s.answers.length===3){$('#board').innerHTML=`<div class="photoresult"><span class="eyebrow">A LITTLE JOURNEY THROUGH TIME</span><h2>${s.answers.reduce((n,a)=>n+a.points,0)} <small>/ 3,000</small></h2><p>Every photograph has a story. Here are the moments you discovered.</p></div>`+set.map((p,i)=>`<div class="recap"><img src="${p.image}" alt="${p.alt}"><div><strong>${p.year} · ${p.title}</strong><p>${s.answers[i].revealed?'Answer revealed':`You guessed ${s.answers[i].guess} · ${s.answers[i].points} points`}</p>${p.why?`<p class="why">${p.why}</p>`:''}<a href="${p.source}" target="_blank" rel="noopener">Photo & story ↗</a></div></div>`).join('');msg('Three discoveries, at your own pace.');return}let p=set[index],a=s.answers[index],lo=difficulty===0?Math.max(1850,Math.floor(p.year/25)*25):1850,hi=difficulty===0?Math.min(2025,lo+24):2025,start=s.pendingYear||Math.round((lo+hi)/2);$('#board').innerHTML=`<div class="roundline"><span>Photograph ${index+1} of 3</span><span>${s.answers.reduce((n,a)=>n+a.points,0)} points</span></div><div class="photoframe"><img id="archivephoto" src="${p.image}" alt="${p.alt}"><p id="photoerror" hidden>Photo could not load. Please reopen the puzzle to try again.</p></div><aside class="photo-clue"><strong>A little clue</strong><p>${photoClue(p)}</p></aside><label class="yearlabel" for="year">Your guess <input id="year" type="number" min="${lo}" max="${hi}" value="${start}" ${a?'disabled':''}></label><input id="yearslider" aria-label="Guess the photograph year" type="range" min="${lo}" max="${hi}" value="${start}" ${a?'disabled':''}><div class="rangeends"><span>${lo}</span><span>${hi}</span></div><p class="small">${difficulty===0?"A little help: this photograph falls within the date window above.":difficulty===1?"Look for clues: "+p.alt.replace(/\b(?:18|19|20)\d{2}\b/g,'[year hidden]'):"Look closely at clothing, technology and surroundings."}</p><div id="photoreveal"></div><p class="credits">Photo dates follow their source catalogues. Credits and original source links appear after each guess. Inspired by <a href="https://www.chronophoto.app/" target="_blank" rel="noopener">Chronophoto</a>. Independent game; archive credits appear after each guess.</p>`;let img=$('#archivephoto');let ready=false;let guessButton;img.onload=()=>{ready=true;if(guessButton)guessButton.disabled=false};img.onerror=()=>{$('#photoerror').hidden=false;if(guessButton)guessButton.disabled=true};const sync=(v)=>{s.pendingYear=+v;$('#year').value=v;$('#yearslider').value=v;persist()};$('#yearslider').oninput=e=>sync(e.target.value);$('#year').oninput=e=>{s.pendingYear=+e.target.value;$('#yearslider').value=e.target.value;persist()};function reveal(){let a=s.answers[index];$('#year').disabled=true;$('#yearslider').disabled=true;$('#photoreveal').innerHTML=`<div class="reveal"><span class="eyebrow">THE YEAR WAS</span><h2>${p.year}</h2><strong>${p.title}</strong><p>${p.story}</p>${p.why?`<p class="why"><strong>Why it mattered:</strong> ${p.why}</p>`:''}<p>Your guess: ${a.guess} · ${Math.abs(a.guess-p.year)} years away · <strong>${a.points} points</strong></p><a href="${p.source}" target="_blank" rel="noopener">${p.credit} · Source ↗</a>${p.licenseUrl?` · <a href="${p.licenseUrl}" target="_blank" rel="noopener">Licence ↗</a>`:""}</div>`;$('#actions').innerHTML='';action(index===2?'See my discoveries':'Next photograph',()=>{if(index===2){s.done=true;persist();setup();draw()}else{index++;draw()}})}guessButton=action('Reveal the year',()=>{let g=Number($('#year').value);if(!ready&&!(img.complete&&img.naturalWidth))return msg('Let the photograph finish loading first.');if(!Number.isInteger(g)||g<lo||g>hi)return msg(`Choose a whole year between ${lo} and ${hi}.`);s.answers[index]={guess:g,points:Math.max(0,1000-20*Math.abs(g-p.year))};delete s.pendingYear;if(s.answers.length===3)s.done=true;persist();setup();msg('');reveal()});guessButton.disabled=!(img.complete&&img.naturalWidth);if(a)reveal()}draw()}
function adjacent(i,width,size){return [i-width,i+width,i%width?i-1:-1,i%width<width-1?i+1:-1].filter(j=>j>=0&&j<size)}
function neighbourStats(board,width,threshold=0,challenge=false){let statuses=board.map((v,i)=>{if(!v)return null;let ns=adjacent(i,width,board.length).map(j=>board[j]).filter(Boolean),same=ns.filter(n=>n===v).length;return {happy:challenge?same>0&&(difficulty===0||same<ns.length)&&(difficulty!==2||same<=2):ns.length===0||same/ns.length>=threshold/100,same,total:ns.length}});let occupied=statuses.filter(Boolean),edges=occupied.reduce((n,s)=>n+s.total,0),same=occupied.reduce((n,s)=>n+s.same,0);return {statuses,happy:occupied.filter(s=>s.happy).length,total:occupied.length,similarity:edges?Math.round(same/edges*100):0}}
function neighbourModel(d){let solution=Array.from({length:16},(_,i)=>i<12?1+i%2:0),r=rng(puzzleSeed(d)+'neighbours');let board=shuffle(solution,r);return{board,solution}}
function neighbours(){let s=state(6);s.mode||='challenge';s.board||=neighbourModel(day).board;s.history||=[];s.threshold??=35;let selected=null;$('#rules').textContent='A tiny world to think with. Try the daily puzzle, then explore how changing one preference changes a whole neighbourhood.';function draw(){let sandbox=s.mode==='sandbox';if(sandbox&&!s.sandbox){s.sandbox=shuffle([...Array(14).fill(1),...Array(14).fill(2),...Array(8).fill(0)],rng(day+'sandbox'));s.steps=0}let board=sandbox?s.sandbox:s.board,width=sandbox?6:4,st=neighbourStats(board,width,s.threshold,!sandbox);$('#actions').innerHTML='';$('#board').innerHTML=`<div class="modebar"><button class="btn ${sandbox?'secondary':''}" id="challengeMode">Daily puzzle</button><button class="btn ${sandbox?'':'secondary'}" id="sandboxMode">What if…?</button></div><p class="instruction">${sandbox?'Shapes want at least <strong>'+s.threshold+'%</strong> of their occupied neighbours to be the same shape. Only unhappy shapes move. Empty squares and diagonals do not count.':'Help all 12 shapes have <strong>'+(difficulty===0?'at least one same-shape neighbour':difficulty===1?'at least one same-shape and one different-shape neighbour':'one or two same-shape neighbours AND at least one different-shape neighbour')+'</strong>. Only up, down, left and right count. Tap any shape, then an empty space to move it.'}</p>${sandbox?`<label class="sliderlabel" for="preference">Same-shape preference: <strong>${s.threshold}%</strong></label><input id="preference" type="range" min="0" max="100" step="5" value="${s.threshold}">`:''}<div class="neighbourmetrics"><span><strong>${st.happy}/${st.total}</strong> content shapes</span><span><strong>${sandbox?st.similarity+'%':s.history.length}</strong> ${sandbox?'same-shape links':'moves'}</span></div><div class="neighbourgrid" style="grid-template-columns:repeat(${width},1fr)">${board.map((v,i)=>`<button class="neighbour ${v?'shape'+v:'empty'} ${st.statuses[i]?.happy?'content':''} ${selected===i?'selected':''}" data-neighbour="${i}" aria-label="Row ${Math.floor(i/width)+1}, column ${i%width+1}: ${v?(v===1?'triangle':'square')+', '+(st.statuses[i].happy?'content':'unhappy'):'empty space'}">${v?neighbourFace(v,st.statuses[i].happy):'<span aria-hidden="true">+</span>'}</button>`).join('')}</div><p class="small">Smiling = content · worried = needs a neighbour · outlined ring = selected</p>${sandbox?`<p class="experimentnote">${st.happy===st.total?'Everyone is content, so nobody moves. Try a different preference or a fresh arrangement.':'Make a prediction, then advance the world. Does a small preference produce larger clusters?'}<br><br>This is a simplified model, not a prediction about real people. A higher same-shape-link percentage means more clustering.</p>`:''}<p class="credits">Inspired by <a href="https://ncase.me/polygons/" target="_blank" rel="noopener">Parable of the Polygons</a> by Vi Hart & Nicky Case. Original implementation and puzzle rules for Little Sparks.</p>`;
$('#challengeMode').onclick=()=>{s.mode='challenge';selected=null;persist();draw();msg('')};$('#sandboxMode').onclick=()=>{s.mode='sandbox';selected=null;persist();draw();msg('')};if(sandbox)$('#preference').onchange=e=>{s.threshold=+e.target.value;selected=null;persist();draw()};document.querySelectorAll('[data-neighbour]').forEach(b=>b.onclick=()=>{let i=+b.dataset.neighbour;if(!sandbox&&s.done)return msg('You solved today’s neighbourhood! Try the What if…? sandbox.');if(board[i]){if(sandbox&&st.statuses[i].happy)return msg('This shape is content. Only unhappy shapes move in the sandbox.');selected=selected===i?null:i;draw();msg(selected===null?'':'Now choose an empty square.')}else if(selected!==null){if(!sandbox)s.history.push(board.slice());board[i]=board[selected];board[selected]=0;selected=null;persist();draw();check()}else msg('Select a shape first, then an empty square.')});function check(){if(!sandbox&&neighbourStats(s.board,4,0,true).happy===12){s.done=true;persist();setup();msg('A neighbourhood with room for both familiarity and variety. Beautifully done!')}else msg('')}
if(sandbox){action('Advance 10 moves',()=>{let r=rng(day+'step'+(s.steps||0));let moved=0;for(let n=0;n<10;n++){let stats=neighbourStats(s.sandbox,6,s.threshold),unhappy=stats.statuses.map((v,i)=>v&&!v.happy?i:-1).filter(i=>i>=0),empty=s.sandbox.map((v,i)=>v===0?i:-1).filter(i=>i>=0);if(!unhappy.length)break;let from=unhappy[Math.floor(r()*unhappy.length)],to=empty[Math.floor(r()*empty.length)];s.sandbox[to]=s.sandbox[from];s.sandbox[from]=0;moved++;s.steps=(s.steps||0)+1}selected=null;persist();draw();msg(moved?moved+' moves. What changed?':'No unhappy shapes: this world is stable. Change the preference to experiment.')});action('Fresh arrangement',()=>{s.sandbox=null;selected=null;persist();draw();persist();msg('Same starting world, ready for a different experiment.');},true)}else{action('Undo',()=>{if(s.done)return msg('Today’s puzzle is complete. The sandbox is ready to explore.');if(s.history.length)s.board=s.history.pop();selected=null;persist();draw();msg('')},true);action('Start over',()=>{if(s.done)return msg('Today’s puzzle is complete. The sandbox is ready to explore.');s.board=neighbourModel(day).board;s.history=[];selected=null;persist();draw();msg('')},true);action('A gentle hint',()=>msg('Try alternating columns of triangles and squares across three full rows. Vertical neighbours match; horizontal neighbours differ.'),true);if(s.done)msg('✓ You brought the whole neighbourhood together.')}}draw()}
